// The browser preview's data says everything the type says it does.
//
// `fixture.json` is generated by `xcal ls --json` against a real share, which
// is what stops the preview drifting from what the engine produces. What it
// does not stop is the *type* moving on: the Added column added `addedMs` to
// `Entry` and nobody regenerated, so every row in the preview rendered
// "NaN undefined NaN, NaN:NaN" — a field the type promises, absent from the
// data, and TypeScript none the wiser because the JSON is imported as a
// module and structurally typed.
//
// So the fields are listed here as well. A field added to `Entry` fails this
// until the fixture carries it, which is the only moment anyone would think
// to regenerate.

import { describe, expect, it } from "vitest";
import fixture from "./fixture.json";

/** Every field of `Entry` in `types.ts`. Keep the two together. */
const ENTRY_FIELDS = [
  "name",
  "path",
  "kind",
  "size",
  "modifiedMs",
  "addedMs",
  "mode",
  "linkTarget",
  "kindLabel",
  "kindCategory",
  "hidden",
] as const;

describe("the preview's fixture", () => {
  it("has entries to check", () => {
    // Guards the test itself: an empty listing would satisfy every loop below.
    expect(fixture.entries.length).toBeGreaterThan(5);
  });

  it("gives every entry every field an Entry has", () => {
    for (const entry of fixture.entries) {
      const present = Object.keys(entry);
      for (const field of ENTRY_FIELDS) {
        expect(present, `${entry.name} is missing ${field}`).toContain(field);
      }
    }
  });

  it("carries no field an Entry does not have", () => {
    // The other direction, because a stale field is a fixture describing an
    // engine that no longer exists.
    for (const entry of fixture.entries) {
      for (const field of Object.keys(entry)) {
        expect(ENTRY_FIELDS as readonly string[], `${entry.name} has ${field}`).toContain(field);
      }
    }
  });
});
